namespace Ncw.Protocol.Tests;

/// <summary>
/// 供应商自动发现 DTO 的冻结向量(协议 v1,能力 <c>providers.discovery</c> 批次生成)。旧向量不动:这一批只新增方法和载荷类型。
/// 这些测试失败说明某个 DTO 的键名 / 形状变了,那必须升协议版本或加能力开关,不能直接改向量(见 <see cref="ProviderDiscoveryDtoTests"/>)。
/// </summary>
internal static class GoldenV1ProviderDiscovery
{
    public const string Scan =
        "";
    public const string ImportParams =
        "81a349647392b063316630613262336334643565366637b030613162326333643465356636303731";
    public const string Import =
        "";

    public static string Of(string name) => name switch
    {
        "discovery.scan" => Scan,
        "discovery.importParams" => ImportParams,
        "discovery.import" => Import,
        _ => throw new ArgumentOutOfRangeException(nameof(name), name, null),
    };
}
